{
  "title": "Tax filing, domain funding, and product development discussion",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing challenges and calculator limitations",
      "claims": [
        {
          "text": "Paying aunt Sveta 500 UAH enabled a correct re‑filing that cost about 1 000 UAH, avoiding larger penalties.",
          "evidence": [1]
        },
        {
          "text": "The tax filing process is described as taking at most an hour per day using Excel.",
          "evidence": [5]
        },
        {
          "text": "The main difficulty is ensuring the correct columns and values are used, not the calculation itself.",
          "evidence": [8]
        },
        {
          "text": "The calculator used works only with a UAH‑based FOP, requiring conversion using the daily exchange rate for other currencies.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-funding",
      "title": "Domain purchase and funding skepticism",
      "claims": [
        {
          "text": "No domain has been purchased yet.",
          "evidence": [2]
        },
        {
          "text": "Buying the FOP calculator is suggested as a way to generate funds for a domain.",
          "evidence": [4]
        },
        {
          "text": "There is skepticism that a domain will be bought; it is described as a raw, low‑value item.",
          "evidence": [9,10]
        }
      ]
    },
    {
      "id": "product-profitability",
      "title": "Web product profitability and market outlook",
      "claims": [
        {
          "text": "A web‑based product is considered less profitable than Android/iOS, suffers from poor SEO, no external traffic, no ad revenue, and low user retention due to early paywalls.",
          "evidence": [11]
        },
        {
          "text": "Fast delivery (under one week) and a cross‑platform Flutter stack are recommended to speed up time‑to‑market.",
          "evidence": [12]
        },
        {
          "text": "The author doubts the product will sell, betting that no one will purchase it within months.",
          "evidence": [17]
        },
        {
          "text": "Technical/managerial/sales posts on LinkedIn have dropped below 50% of the audience.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "cross-platform-design",
      "title": "Cross‑platform development approach",
      "claims": [
        {
          "text": "Flutter is chosen as the cross‑platform development stack for rapid implementation.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "app-architecture-security",
      "title": "App architecture, pricing, and security choices",
      "claims": [
        {
          "text": "The app is marketed as a local‑first solution that fetches USD/UAH rates every five minutes and performs calculations instantly in the browser.",
          "evidence": [29]
        },
        {
          "text": "The product is priced at 299 UAH, with a 100 % discount promo code stored locally.",
          "evidence": [20]
        },
        {
          "text": "The required password is stored inside the application bundle.",
          "evidence": [23]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Use Flutter as the cross‑platform development stack.",
      "evidence": [12]
    },
    {
      "text": "Target a delivery time of less than one week for product release.",
      "evidence": [12]
    },
    {
      "text": "Implement the app as a local‑first web application that retrieves exchange rates every five minutes and performs client‑side calculations.",
      "evidence": [29]
    },
    {
      "text": "Set the product price at 299 UAH and include a 100 % discount promo code stored locally.",
      "evidence": [20]
    },
    {
      "text": "Store the password inside the app bundle.",
      "evidence": [23]
    },
    {
      "text": "Restrict the calculator to UAH‑only FOP without foreign‑currency support.",
      "evidence": [19]
    },
    {
      "text": "Adopt a design approach of copying popular solutions and adding minor customizations.",
      "evidence": [12]
    }
  ],
  "openQuestions": [
    {
      "text": "Is the tax filing procedure really limited to an hour per day using Excel?",
      "evidence": [5]
    }
  ]
}
